/* The module extends the existing navigation/theme; it does not replace any
 * course state. Question data and progress stay in this browser, as elsewhere
 * on this Site. Remote bank text is fetched only after an explicit selection. */
hubSubjects.civil={name:'考公刷题',mark:'测',tag:'练题，也练方法',description:'行测专项、真题套卷、快速解题、错题复盘与间隔复习。',tone:'blue'};
hubCurriculum.civil=[];
let civilPane='home',civilCatalog=null,civilCatalogError='',civilCatalogPage=0,civilPaperQuery='',civilPaperModules={},civilYear='全部',civilRegion='全部',civilMethodTier='全部',civilMethodCategory='全部',civilMethodId='',civilReviewOnly='wrong',civilLoadMessage='',civilLoading=false,civilDialog=null,civilReviewId='',civilImages=new Map(),civilImageURLs=new Map(),civilDBPromise=null,civilReady=false;
let civilState={version:1,active:null,history:[],records:{},bookmarks:[],notes:{},methods:[],dailyGoal:10};
try{const s=JSON.parse(localStorage.getItem('learning-civil-v1'));if(s?.version===1&&civilValidState(s))civilState={...civilState,...s};}catch(e){}

function civilValidState(s){if(!s||typeof s.records!=='object'||!s.records||!Array.isArray(s.history)||!Array.isArray(s.bookmarks)||!s.notes||typeof s.notes!=='object')return false;const sessionOK=x=>x&&typeof x.id==='string'&&Array.isArray(x.questions)&&x.questions.length<=1000&&x.questions.every(id=>typeof id==='string'&&!['__proto__','constructor','prototype'].includes(id))&&['exam','practice'].includes(x.mode)&&Number.isInteger(x.index)&&x.index>=0&&x.index<x.questions.length&&x.answers&&x.submitted&&Array.isArray(x.flags)&&Number.isFinite(x.started)&&Number.isFinite(x.elapsed)&&Number.isFinite(x.activeSince);return (!s.active||sessionOK(s.active))&&s.history.every(sessionOK)&&Object.entries(s.records).every(([id,r])=>!['__proto__','constructor','prototype'].includes(id)&&r&&Number.isFinite(r.attempts)&&Number.isFinite(r.correct)&&Number.isFinite(r.wrong)&&Array.isArray(r.days)&&r.days.every(d=>typeof d==='string'));}
const civilBank=new Map(civilSeed.map(q=>[q.id,q]));
if(civilState.active&&!civilState.active.finished&&civilState.active.mode==='practice'){civilState.active.paused=true;civilState.active.activeSince=Date.now();}
function civilPersist(){try{localStorage.setItem('learning-civil-v1',JSON.stringify(civilState));return true;}catch(e){toast('存储空间不足，当前答案仍保留在页面中；请先导出备份。');return false;}}
function civilDB(){if(!civilDBPromise)civilDBPromise=new Promise((resolve,reject)=>{if(!globalThis.indexedDB)return reject(Error('当前浏览器不能保存题库。'));const req=indexedDB.open('learning-civil-bank',1);req.onupgradeneeded=()=>req.result.createObjectStore('questions',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});return civilDBPromise;}
async function civilDBRead(id){try{const db=await civilDB();return await new Promise((resolve,reject)=>{const tx=db.transaction('questions'),req=tx.objectStore('questions').get(id);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}catch(e){return null;}}
async function civilRemember(questions){for(const q of questions)civilBank.set(q.id,q);try{const db=await civilDB();await new Promise((resolve,reject)=>{const tx=db.transaction('questions','readwrite');for(const q of questions)tx.objectStore('questions').put(q);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}catch(e){toast('题目已载入；当前浏览器未保存题库，刷新后可能需要重新载入原卷。');}}
async function civilHydrate(){const ids=new Set([...(civilState.active?.questions||[]),...civilState.bookmarks,...Object.keys(civilState.records),...civilState.history.flatMap(s=>s.questions)]);await Promise.all([...ids].filter(id=>!civilBank.has(id)).map(async id=>{const q=await civilDBRead(id);if(q)civilBank.set(id,q);}));civilReady=true;if(view==='civil'||view==='subject'&&hubSubject==='civil')render();}
function civilSession(){return civilState.active;}
function civilLookup(id){const q=civilBank.get(id);return q&&civilState.notes[id]?.doubt?{...q,reviewRequired:true}:q;}
function civilCurrent(){return civilLookup(civilSession()?.questions[civilSession().index]);}
function civilClock(ms){const n=Math.floor(Math.max(0,ms)/1000);return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');}
function civilToday(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function civilRecordResult(q,result){const old=civilState.records[q.id]||{attempts:0,correct:0,wrong:0,days:[]};if(result==='ungraded'||result==='blank')return;const now=Date.now(),day=civilToday();civilState.records[q.id]={...old,attempts:old.attempts+1,correct:old.correct+(result==='correct'),wrong:old.wrong+(result==='wrong'),latest:result,lastAt:now,days:[...new Set([...old.days,day])].slice(-120),review:Civil.schedule(old.review,result==='correct'?4:1,now)};}
function civilGo(pane='home'){civilPane=pane;view='civil';hubSubject='civil';render();window.scrollTo({top:0,behavior:'instant'});if(pane==='papers'&&!civilCatalog&&!civilLoading)civilLoadCatalog();}
async function civilLoadCatalog(){civilLoading=true;civilCatalogError='';try{const r=await fetch('data/civil/catalog.json');if(!r.ok)throw Error('真题目录加载失败。');civilCatalog=await r.json();}catch(e){civilCatalogError=e.message;}civilLoading=false;if(view==='civil')render();}
function civilGroups(questions){const groups=new Map();for(const q of questions){const key=q.materialId||q.id;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(q);}return [...groups.values()];}
function civilPick(questions,count,random=true,seed=''){const groups=civilGroups(questions);if(random)groups.sort((a,b)=>{const x=parseInt(Civil.hash(seed+a[0].id),16),y=parseInt(Civil.hash(seed+b[0].id),16);return x-y;});const picked=[];for(const group of groups){if(picked.length>=count)break;picked.push(...group);}return picked;}
function civilStart(questions,mode='practice',minutes=20,label='专项练习',replace=false){if(!questions.length)return toast('当前条件下没有题目，请换一个分类或先载入真题。');if(!replace&&civilSession()&&!civilSession().finished){civilDialog={type:'replace',questions,mode,minutes,label};render();return;}if(civilSession()){Civil.recordTime(civilSession());civilState.history=[civilSession(),...civilState.history.filter(s=>s.id!==civilSession().id)].slice(0,30);}civilState.active=Civil.createSession(questions,mode,minutes);civilState.active.label=label;civilState.active.recorded=[];civilPersist();civilDialog=null;civilGo('question');}
function civilFinish(){const s=civilSession();if(!s||s.finished)return;Civil.finish(s,id=>civilLookup(id),s.mode==='exam'?Math.min(Date.now(),s.deadline):Date.now());s.recorded??=[];for(const id of s.questions){if(s.recorded.includes(id))continue;const q=civilLookup(id);if(q)civilRecordResult(q,s.submitted[id]?.result);s.recorded.push(id);}civilDialog=null;civilPersist();if(view==='civil')civilGo('report');}
function civilTick(){const s=civilSession();if(!s||s.finished||s.paused||!civilReady)return;if(s.mode==='exam'&&Date.now()>=s.deadline){civilFinish();return;}const node=$('civil-time');if(node)node.textContent=s.mode==='exam'?civilClock(s.deadline-Date.now()):civilClock(s.elapsed+(s.submitted[s.questions[s.index]]?0:Date.now()-s.activeSince));}
function civilLocalImage(path,src){const direct=civilImages.get(src.split('/').at(-1));if(direct){if(!civilImageURLs.has(src))civilImageURLs.set(src,URL.createObjectURL(direct));return civilImageURLs.get(src);}const url=Civil.imageURL(path,src);if(!url)return null;const suffix=decodeURIComponent(url.split('/main/')[1]),file=civilImages.get(suffix);if(!file)return null;if(!civilImageURLs.has(suffix))civilImageURLs.set(suffix,URL.createObjectURL(file));return civilImageURLs.get(suffix);}
function civilHTML(text,q={}){return Civil.safeHTML(text,q.path||'original.md',civilLocalImage);}
function civilSource(q){return q.path?`<a href="https://github.com/ERRRC/xingcezhenti/blob/main/${q.path.split('/').map(encodeURIComponent).join('/')}" target="_blank" rel="noopener noreferrer">原题来源 · qid ${esc(q.qid)}</a>`:`<span>${esc(q.sourceType||'原创训练')}</span>`;}
function civilShell(content){return `<main class="hub-main civil-main"><div class="civil-heading"><div><div class="eyebrow">知行学习室 / 考公刷题</div><h1>${({home:"行测练习台",papers:"历年真题套卷",methods:"快速解题方法课",notebook:"错题与复习",stats:"学习记录与复盘",resources:"资料与题库导入",question:"行测答题",report:"本次练习报告"})[civilPane]||"考公刷题"}</h1></div><span class="chip">与其他课堂独立记录</span></div><nav class="civil-tabs" aria-label="考公模块">${[['home','练习台'],['papers','历年真题'],['methods','快速解题'],['notebook','错题与收藏'],['stats','学习报告'],['resources','资料与导入']].map(([id,title])=>`<button data-civil="pane" data-id="${id}" class="${civilPane===id?'active':''}" ${civilPane===id?'aria-current="page"':''}>${title}</button>`).join('')}</nav>${content}${civilDialogHTML()}<p class="small-note civil-footer">题库与学习记录保存在当前浏览器，暂不跨设备同步；可导出备份。原创题与真题分开标注，原仓库答案和解析未逐题核验；存疑题可标记待核，不计自动评分。</p></main>`;}
function civilHomeHTML(){const records=Object.values(civilState.records),today=records.filter(r=>r.days.includes(civilToday())).length,wrong=records.filter(r=>r.latest==='wrong').length,due=records.filter(r=>r.review?.due<=Date.now()).length,s=civilSession();return `<section class="civil-summary"><div><small>今日做题</small><b>${today}<em> / ${civilState.dailyGoal}</em></b></div><div><small>待复盘错题</small><b>${wrong}</b></div><div><small>到期复习</small><b>${due}</b></div><div><small>已载入题目</small><b>${civilBank.size}</b></div></section>${s&&!s.finished?`<section class="civil-resume"><div><b>继续：${esc(s.label)}</b><p>第 ${s.index+1}/${s.questions.length} 题 · ${s.mode==='exam'?'限时模式继续计时':'练习模式可暂停'}</p></div><button class="primary" data-civil="resume">继续作答</button></section>`:''}<div class="civil-start-grid"><section class="section"><div class="eyebrow">先练一组 / 一步一步上手</div><h2>今天从哪一类开始？</h2><p>练习模式提交后看解析；限时模式交卷后统一看答案。选择选项不会自动跳到下一题。</p><form id="civil-start-form"><div class="civil-controls"><label>模块<select id="civil-category"><option value="全部">全部模块</option>${Civil.categories.map(c=>`<option>${c}</option>`).join('')}</select></label><label>题量<select id="civil-count">${[10,20,30,50].map(n=>`<option>${n}</option>`).join('')}</select></label><label>方式<select id="civil-mode"><option value="practice">练习 · 逐题提交</option><option value="exam">限时 · 交卷看解析</option></select></label><label>限时（分钟）<input id="civil-minutes" type="number" min="1" max="240" value="20"></label><label>题目顺序<select id="civil-order"><option value="difficulty">训练题由浅入深</option><option value="random">打散材料组</option><option value="sequence">顺序练习</option></select></label><label>题目来源<select id="civil-pool"><option value="all">已载入全部</option><option value="original">本站原创</option><option value="past">已载入真题</option></select></label></div><button class="primary" type="submit">开始专项练习</button><button class="secondary" type="button" data-civil="daily">每日一练</button></form><p class="small-note">材料组一起抽取，实际题量可能略多。本站原创题适合入门，不冒充考试难度；先载入真题后可选“已载入真题”。</p></section><aside class="section civil-next"><h2>把速度练出来</h2><ol><li>基础：概念、比例、公式与条件。</li><li>熟练：百化分、代入、赋值和结构识别。</li><li>进阶：误差控制、比较与限时取舍。</li></ol><button class="secondary" data-civil="pane" data-id="methods">从快速解题方法课开始</button><button class="secondary" data-civil="review-due">复习到期题目</button><button class="text-button" data-civil="pane" data-id="papers">按年份、地区选择真题</button></aside></div><div class="civil-modules">${Civil.categories.map((c,i)=>{const ids=[...civilBank.values()].filter(q=>q.category===c),done=ids.filter(q=>civilState.records[q.id]).length;return `<button data-civil="module" data-id="${c}" class="section"><span class="path-number">0${i+1}</span><h2>${c}</h2><p>${ids.length} 道已载入 · ${done} 道已练</p><span>练这一模块</span></button>`;}).join('')}</div>`;}
function civilQuestionHTML(){const s=civilSession(),q=civilCurrent();if(!s)return '<section class="section"><p>先选择一组题开始练习。</p><button data-civil="pane" data-id="home">返回练习台</button></section>';if(!q)return '<section class="section"><h2>当前题目尚未恢复</h2><p>请重新载入原卷，或从备份导入题目，原答题记录仍保留。</p><button data-civil="pane" data-id="papers">查找原卷</button></section>';const result=s.submitted[q.id],reveal=s.mode!=='exam'&&!!result||s.finished,selected=s.answers[q.id]||[],bookmarked=civilState.bookmarks.includes(q.id),flag=s.flags.includes(q.id);return `<div class="civil-session-bar"><div><b>${esc(s.label)}</b><p>${s.mode==='exam'?'限时模式 · 交卷后统一解析':'练习模式 · 答完手动提交'} · ${s.index+1}/${s.questions.length}</p></div><div class="civil-time"><span>${s.mode==='exam'?'剩余':'已用'}</span><b id="civil-time">${s.mode==='exam'?civilClock(s.deadline-Date.now()):civilClock(s.elapsed+(s.paused?0:Date.now()-s.activeSince))}</b></div><button class="secondary" data-civil="pause" ${s.mode==='exam'||s.finished?'disabled':''}>${s.paused?'继续练习':'暂停'}</button><button class="primary" data-civil="ask-finish" ${s.finished?'disabled':''}>交卷</button></div>${s.paused?'<section class="civil-paused"><h2>练习已暂停</h2><p>暂停期间不计用时，继续后恢复当前题目。</p><button class="primary" data-civil="pause">继续练习</button></section>':`<div class="civil-exercise-grid"><article class="section civil-question"><div class="civil-question-meta"><span class="chip">${esc(q.category)} · ${esc(q.subtype||'综合')}</span><span>${q.answer.length>1?'多选 · 全对得分':q.reviewRequired?'答案待核':'单选'}</span><button class="text-button" data-civil="bookmark">${bookmarked?'已收藏':'收藏'}</button><button class="text-button" data-civil="flag">${flag?'已标记':'标记稍后做'}</button></div>${q.material?`<details class="civil-material" open><summary>阅读材料 · 同组小题共享</summary><div>${civilHTML(q.material,q)}</div></details>`:''}<div class="civil-stem">${civilHTML(q.stem,q)}</div><fieldset class="civil-options"><legend>${q.answer.length>1?'请选择所有符合条件的选项':'请选择一个答案，选完不会自动跳题'}</legend>${q.options.map(o=>{const state=reveal?(q.answer.includes(o.key)?'correct':selected.includes(o.key)?'incorrect':''):selected.includes(o.key)?'selected':'';return `<label class="civil-option ${state}" for="civil-option-${o.key}"><input id="civil-option-${o.key}" name="civil-answer" type="${q.answer.length>1?'checkbox':'radio'}" value="${o.key}" ${selected.includes(o.key)?'checked':''} ${result||s.finished?'disabled':''}><b>${o.key}</b><div>${civilHTML(o.text,q)}</div></label>`;}).join('')}</fieldset><div class="civil-answer-actions">${s.mode==='practice'&&!s.finished?`<button class="primary" data-civil="submit-one" ${!selected.length||result?'disabled':''}>${result?'已提交本题':'提交本题，查看解析'}</button>`:`<span class="small-note">${s.finished?'本次答题已结束':'答案已自动保存，交卷前可以修改。'}</span>`}<span role="status">${result&&reveal?result.result==='correct'?'✓ 回答正确':result.result==='wrong'?'本题答错，已加入错题本':result.result==='blank'?'本题未作答':'答案待核，不计自动评分':''}</span></div>${reveal?civilExplanationHTML(q):''}<div class="civil-question-footer">${civilSource(q)}<span>${esc(q.paper)}</span></div></article><aside class="section civil-answer-card"><h2>答题卡</h2><p>${Object.keys(s.answers).filter(id=>s.answers[id]?.length).length}/${s.questions.length} 已选 · ${s.flags.length} 已标记</p><div class="civil-card-grid">${s.questions.map((id,i)=>{const status=s.submitted[id]?.result;return `<button data-civil="jump" data-index="${i}" class="${i===s.index?'current ':''}${s.mode==='exam'&&!s.finished?(s.answers[id]?.length?'answered':''):status|| (s.answers[id]?.length?'answered':'')} ${s.flags.includes(id)?'flagged':''}" aria-label="第${i+1}题${s.flags.includes(id)?'，已标记':''}" ${i===s.index?'aria-current="true"':''}>${i+1}</button>`;}).join('')}</div><p class="small-note">蓝：已选 · 虚线：标记 · 提交后绿：正确，红：错误。限时模式交卷前不显示对错。</p></aside></div>`}<div class="civil-bottom"><button class="secondary" data-civil="move" data-delta="-1" ${s.index===0||s.paused?'disabled':''}>上一题</button><span>手动切换题目，未答题可稍后从答题卡返回</span><button class="primary" data-civil="move" data-delta="1" ${s.index===s.questions.length-1||s.paused?'disabled':''}>下一题</button>${s.finished?'<button class="secondary" data-civil="pane" data-id="report">查看报告</button>':''}</div>`;}
function civilExplanationHTML(q){const note=civilState.notes[q.id]||{},methods=civilMethods.filter(m=>m.id===q.method);return `<section class="civil-explanation"><h2>答案与解析</h2><p><b>${q.reviewRequired?'答案待人工核对':q.answer.join('、')}</b> · ${q.source==='知行学习室原创'?'本站原创解析':'原仓库解析（未逐题核验）'}</p><div>${civilHTML(q.explanation,q)}</div>${methods.map(m=>`<div class="worked-example"><b>更快的路径：${m.title}</b><p>${m.fast}</p><p>边界：${m.risk}</p><button class="text-button" data-civil="method" data-id="${m.id}">读方法与适用条件</button></div>`).join('')}<div class="civil-note"><h3>错因与复盘</h3><label for="civil-reason">错在最早哪一步？</label><select id="civil-reason">${['未分类','读题遗漏','概念不清','方法选择','计算错误','时间分配','答案争议'].map(r=>`<option ${note.reason===r?'selected':''}>${r}</option>`).join('')}</select><label for="civil-note">写一句：下次看到什么信号，应该怎样做？</label><textarea id="civil-note" rows="3" maxlength="4000">${esc(note.text||'')}</textarea><button class="secondary" data-civil="save-note" data-id="${q.id}">保存复盘</button><button class="text-button" data-civil="question-doubt" data-id="${q.id}">${note.doubt?'已标记待核':'标记此题答案待核'}</button></div></section>`;}
function civilReportHTML(){const s=civilSession();if(!s?.finished)return '<section class="section"><h2>交卷后生成报告</h2><button class="primary" data-civil="resume">回到当前练习</button></section>';const r=Civil.report(s,id=>civilBank.get(id));return `<section class="section"><div class="page-head"><div><div class="eyebrow">本次练习报告 / ${esc(s.label)}</div><h2>把失分点变成下一次的动作</h2><p>仅为本站等权题目统计，不是官方行测成绩或预测分。</p></div><button class="primary" data-civil="review-current">逐题看解析</button></div><div class="civil-summary"><div><small>答对 / 总题量</small><b>${r.right}<em> / ${r.total}</em></b></div><div><small>已判题正确率</small><b>${r.accuracy}%</b></div><div><small>错误 / 未答 / 待核</small><b>${r.wrong}<em> / ${r.blank} / ${r.ungraded}</em></b></div><div><small>有效用时</small><b>${civilClock(r.elapsed)}</b></div></div><div class="civil-module-report">${Object.entries(r.modules).map(([name,m])=>`<div><b>${name}</b><progress max="${m.total}" value="${m.correct}" aria-label="${name}答对${m.correct}道"></progress><span>${m.correct}/${m.total} · ${civilClock(m.spent)}</span></div>`).join('')}</div><button class="secondary" data-civil="redo-wrong">重做本次错题与未答</button><button class="secondary" data-civil="pane" data-id="notebook">去错题本复盘</button><button class="text-button" data-civil="pane" data-id="home">返回练习台</button></section>`;}
function civilPapersHTML(){if(!civilCatalog)return `<section class="section"><h2>截图题库 · 历年套卷</h2><p role="status">${esc(civilCatalogError||'正在载入 515 套卷目录…')}</p><button class="secondary" data-civil="reload-catalog">重新载入目录</button></section>`;const papers=civilCatalog.papers.filter(p=>(civilYear==='全部'||String(p.year)===civilYear)&&(civilRegion==='全部'||p.region===civilRegion)&&p.title.toLowerCase().includes(civilPaperQuery.toLowerCase()));civilCatalogPage=Math.min(civilCatalogPage,Math.max(0,Math.ceil(papers.length/12)-1));return `<section class="section"><div class="page-head"><div><h2>历年真题 · 原仓库按需读取</h2><p>已接入目录 ${civilCatalog.papers.length} 套；原仓库标注 58,890 题，不表示本设备已下载或核验全部题目。</p></div><a target="_blank" rel="noopener noreferrer" href="https://github.com/ERRRC/xingcezhenti">查看截图中的原项目</a></div><div class="civil-controls"><label>年份<select id="civil-year"><option>全部</option>${[...new Set(civilCatalog.papers.map(p=>p.year))].sort((a,b)=>b-a).map(n=>`<option ${String(n)===civilYear?'selected':''}>${n}</option>`).join('')}</select></label><label>地区<select id="civil-region"><option>全部</option>${[...new Set(civilCatalog.papers.map(p=>p.region))].sort().map(n=>`<option ${n===civilRegion?'selected':''}>${n}</option>`).join('')}</select></label><label class="grow">卷名搜索<input id="civil-paper-query" value="${esc(civilPaperQuery)}" placeholder="例如 国考、山东、行政执法"></label><button class="secondary" data-civil="search-papers">搜索</button></div><p class="small-note">点击载入后，浏览器直接连接 GitHub 读取所选卷；题图与公式图按需加载。地区由卷名辅助识别，最终以卷名及原文为准。网络不可达时，可在“资料与导入”导入 MD、JSON 或原仓库 ZIP。</p><p class="civil-loading" role="status">${esc(civilLoadMessage)}</p></section><div class="civil-paper-grid">${papers.slice(civilCatalogPage*12,civilCatalogPage*12+12).map(p=>`<article class="section"><span class="chip">${p.year} · ${p.region}</span><h3>${esc(p.title)}</h3><p>${p.files.map(f=>f.category).join(' · ')}</p><div class="civil-paper-actions"><button class="primary" data-civil="load-paper" data-id="${p.id}" ${civilLoading?'disabled':''}>载入此卷</button><select aria-label="选择此卷模块" id="paper-module-${p.id}"><option value="全部">全部模块</option>${p.files.map(f=>`<option ${civilPaperModules[p.id]===f.category?'selected':''}>${f.category}</option>`).join('')}</select></div></article>`).join('')||'<p>没有匹配的套卷，请调整条件。</p>'}</div><div class="civil-pagination"><button data-civil="papers-page" data-delta="-1" ${civilCatalogPage===0?'disabled':''}>上一页</button><span>${papers.length} 套 · ${civilCatalogPage+1}/${Math.max(1,Math.ceil(papers.length/12))}</span><button data-civil="papers-page" data-delta="1" ${(civilCatalogPage+1)*12>=papers.length?'disabled':''}>下一页</button></div>`;}
async function civilLoadPaper(id,category='全部'){if(civilLoading)return;const paper=civilCatalog?.papers.find(p=>p.id===id);if(!paper)return;civilLoading=true;civilLoadMessage='正在读取原卷，请稍候…';render();const files=paper.files.filter(f=>category==='全部'||f.category===category),results=await Promise.allSettled(files.map(async f=>{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),25000);try{const r=await fetch('https://raw.githubusercontent.com/ERRRC/xingcezhenti/main/'+f.path.split('/').map(encodeURIComponent).join('/'),{signal:controller.signal});if(!r.ok)throw Error('原卷 HTTP '+r.status);return Civil.parseMarkdown(await r.text(),f.path);}finally{clearTimeout(timer);}}));const questions=[],issues=[];results.forEach((result,i)=>{if(result.status==='fulfilled'){questions.push(...result.value.questions);issues.push(...result.value.issues.map(x=>files[i].category+'：'+x.reason));}else issues.push(files[i].category+'读取失败');});civilLoading=false;if(!questions.length){civilLoadMessage='未能读取原卷。请检查网络或使用文件导入；未开始空白练习。';render();return;}await civilRemember([...new Map(questions.map(q=>[q.id,q])).values()]);civilLoadMessage=`已载入 ${questions.length} 题。${issues.length?'存在 '+issues.length+' 项待核：'+issues.slice(0,4).join('；'):'各模块题量与原文标注一致。'}`;civilDialog={type:'loaded',questions,label:paper.title+(category==='全部'?'':' · '+category),issues};render();}
function civilMethodsHTML(){if(civilMethodId){const m=civilMethods.find(x=>x.id===civilMethodId);return `<button class="text-button" data-civil="method-back">返回方法路线</button><article class="section civil-method-lesson"><span class="chip">${m.tier} · ${m.category} · 方法 ${m.order}</span><h2>${m.title}</h2><p>${m.principle}</p><h3>什么时候用</h3><p>${m.when}</p><pre>${m.formula}</pre><h3>标准过程</h3><ol>${m.steps.map(s=>`<li>${s}</li>`).join('')}</ol><div class="worked-example"><h3>原创例子</h3><p>${m.example}</p><h3>怎样更快</h3><p>${m.fast}</p></div><div class="civil-boundary"><b>不能硬套的情况</b><p>${m.risk}</p></div>${civilDemoHTML(m)}<div class="civil-answer-actions"><button class="primary" data-civil="method-practice" data-id="${m.id}">理解了，做配套题</button><button class="secondary" data-civil="method-done" data-id="${m.id}">${civilState.methods.includes(m.id)?'已记录学过':'记录已读'}</button></div><p class="small-note">本站独立编写的方法讲解与例题。数学恒等式和推理规则是通用方法，不冒称教师独家口诀；教师及社区资源见“资料与导入”。</p></article>`;}return `<section class="section"><h2>由浅入深的快速解题路线</h2><p>先会标准解，再压缩计算。所谓“秒杀”必须有适用条件，不能用口诀替代审题。每张方法卡包含原理、步骤、快解、反例边界与配套题。</p><div class="concept-flow"><span><small>01 · 基础</small>概念与公式</span><span><small>02 · 熟练</small>识别与简化</span><span><small>03 · 进阶</small>误差与取舍</span></div><div class="civil-controls"><label>难度<select id="civil-method-tier">${['全部','基础','熟练','进阶'].map(v=>`<option ${v===civilMethodTier?'selected':''}>${v}</option>`).join('')}</select></label><label>模块<select id="civil-method-category">${['全部','全模块',...Civil.categories].map(v=>`<option ${v===civilMethodCategory?'selected':''}>${v}</option>`).join('')}</select></label></div></section><div class="civil-method-grid">${civilMethods.filter(m=>(civilMethodTier==='全部'||m.tier===civilMethodTier)&&(civilMethodCategory==='全部'||m.category===civilMethodCategory)).map(m=>`<button class="section civil-method-card" data-civil="method" data-id="${m.id}"><span class="chip">${m.tier} · ${m.category}</span><h3>${m.order}. ${m.title}</h3><p>${m.when}</p><span>${civilState.methods.includes(m.id)?'✓ 已读':'读原理、看例子、再练题'}</span></button>`).join('')}</div>`;}
function civilDemoHTML(m){if(['base','fraction-growth','share','weighted','percent'].includes(m.id))return `<section class="civil-demo"><h3>可调演示：现期、基期与增长量</h3><p>改变参数，看精确关系；正增长时，增长量是现期中的一部分。</p><div class="civil-controls"><label>现期C<input id="civil-demo-current" type="number" value="120" min="0"></label><label>增速r（%）<input id="civil-demo-rate" type="number" value="20" min="-99" step="0.1"></label></div><div id="civil-demo-output"></div></section>`;if(m.id==='truncate')return `<section class="civil-demo"><h3>估算误差看得见</h3><p>同时改变估算的分子分母，与精确值比较。误差接近选项间距时就该多算一位。</p><div class="civil-controls"><label>分子<input id="civil-demo-num" type="number" value="1980"></label><label>分母<input id="civil-demo-den" type="number" value="4010"></label><label>近似分子<input id="civil-demo-num2" type="number" value="2000"></label><label>近似分母<input id="civil-demo-den2" type="number" value="4000"></label></div><div id="civil-demo-output"></div></section>`;return '';}
function civilPaintDemo(){const node=$('civil-demo-output');if(!node)return;if($('civil-demo-current')){const c=Number($('civil-demo-current').value),r=Number($('civil-demo-rate').value)/100;if(!Number.isFinite(c)||c<0||!Number.isFinite(r)||r<=-1){node.textContent='现期需非负，增速需大于−100%。';return;}const b=c/(1+r),d=c-b,pct=c>0?Math.min(100,Math.max(0,b/c*100)):0;node.innerHTML=`<div class="civil-growth-bar"><span style="width:${pct}%">基期</span><span style="width:${100-pct}%">增量</span></div><p>基期 B=${b.toFixed(3)}；增长量 Δ=${d.toFixed(3)}；校验 B+Δ=${c.toFixed(3)}。</p>${r<0?'<p>负增长时基期大于现期，条形图不表示负值；请以数值为准。</p>':''}`;}else{const n=Number($('civil-demo-num').value),d=Number($('civil-demo-den').value),n2=Number($('civil-demo-num2').value),d2=Number($('civil-demo-den2').value);if(![n,d,n2,d2].every(Number.isFinite)||d===0||d2===0){node.textContent='请输入有效数字，分母不能为0。';return;}const exact=n/d,approx=n2/d2;node.innerHTML=`<p>精确值 ${(exact*100).toFixed(4)}% · 估算 ${(approx*100).toFixed(4)}%</p><p>绝对误差 ${Math.abs((approx-exact)*100).toFixed(4)} 个百分点${exact===0?'':`；相对误差 ${(Math.abs((approx-exact)/exact)*100).toFixed(3)}%`}。</p>`;}}
function civilNotebookHTML(){const ids=[...civilBank.keys()].filter(id=>{const r=civilState.records[id],n=civilState.notes[id];return civilReviewOnly==='bookmarks'?civilState.bookmarks.includes(id):civilReviewOnly==='doubt'?n?.doubt:civilReviewOnly==='due'?r?.review?.due<=Date.now():r?.latest==='wrong';});return `<section class="section"><div class="page-head"><div><h2>错题不是收藏品，是下一次的动作。</h2><p>重做正确后移出当前错题列表，历史错误次数保留。间隔复习按作答结果更新，答题前看解析不算独立掌握。</p></div><button class="primary" data-civil="practice-notebook" ${ids.length?'':'disabled'}>重练当前列表</button></div><div class="filter-tabs">${[['wrong','当前错题'],['bookmarks','收藏'],['due','到期复习'],['doubt','答案待核']].map(([v,t])=>`<button class="${civilReviewOnly===v?'active':''}" data-civil="notebook-filter" data-id="${v}">${t}</button>`).join('')}</div><div class="civil-notebook-list">${ids.map(id=>{const q=civilBank.get(id),r=civilState.records[id],n=civilState.notes[id];return `<article><div><span class="chip">${q.category}</span><h3>${esc(q.stem.replace(/<[^>]+>/g,'').slice(0,110))}</h3><p>错误 ${r?.wrong||0} 次 · ${esc(n?.reason||'未分类')}${r?.review?' · 计划 '+new Date(r.review.due).toLocaleDateString()+' 复习':''}</p>${n?.text?`<p>${esc(n.text)}</p>`:''}</div><button class="secondary" data-civil="single" data-id="${id}">独立重做</button><button class="text-button" data-civil="inspect" data-id="${id}">看解析与笔记</button></article>`;}).join('')||'<p class="civil-empty">这里暂时没有题目。先完成一次练习；错题会自动记录，也可手动收藏。</p>'}</div></section>`;}
function civilStatsHTML(){const records=Object.entries(civilState.records),attempts=records.reduce((n,[,r])=>n+r.attempts,0),correct=records.reduce((n,[,r])=>n+r.correct,0);return `<section class="section"><h2>学习记录</h2><p>练过 ${records.length} 道不同题，共 ${attempts} 次已判题作答；含重做的正确率 ${attempts?Math.round(correct/attempts*100):0}%。未答和待核不混进已判题正确率。</p><div class="civil-module-report">${Civil.categories.map(c=>{const entries=records.filter(([id])=>civilBank.get(id)?.category===c),done=entries.length,ok=entries.filter(([,r])=>r.latest==='correct').length;return `<div><b>${c}</b><progress max="${done||1}" value="${ok}" aria-label="${c}最近一次答对${ok}道"></progress><span>最近答对 ${ok}/${done}</span></div>`;}).join('')}</div><label>每日目标<input id="civil-goal" type="number" min="1" max="300" value="${civilState.dailyGoal}"></label><button class="secondary" data-civil="save-goal">保存目标</button></section><section class="section"><h2>练习历史</h2>${[civilSession(),...civilState.history].filter(Boolean).map(s=>`<article class="civil-history"><div><b>${esc(s.label)}</b><p>${new Date(s.started).toLocaleString()} · ${s.questions.length}题 · ${s.finished?'已交卷':'未交卷 / 可恢复'}</p></div><button class="secondary" data-civil="history" data-id="${s.id}">${s.finished?'查看记录':'恢复练习'}</button></article>`).join('')||'<p>还没有练习记录。</p>'}</section>`;}
function civilResourcesHTML(){return `<section class="section"><h2>题库导入与学习备份</h2><p>支持截图仓库的 Markdown、JSON 与 ZIP。保留 qid 和原卷信息，不把导入内容自动标为已核验。来源题库中的公式图片也需一起保留。</p><div class="civil-import-actions"><button class="primary" data-civil="import">导入 MD / JSON / ZIP</button><button class="secondary" data-civil="folder">导入原仓库文件夹（电脑）</button><button class="secondary" data-civil="images">补充题图与公式图片</button><button class="secondary" data-civil="export">导出学习备份</button><button class="text-button" data-civil="template">下载 JSON 题目格式</button></div><input id="civil-import-file" type="file" accept=".md,.json,.zip" multiple hidden><input id="civil-folder-file" type="file" webkitdirectory multiple hidden><input id="civil-image-files" type="file" accept="image/png,image/jpeg,image/webp,image/gif" multiple hidden><p class="small-note">备份包含答题、错题、收藏、笔记和相关题目；导入文件不上传。图片文件仅在当前页面会话使用，刷新后可再次选择。ZIP 限400MB、解压总量限600MB；手机优先按卷导入 MD，较大仓库建议电脑用文件夹导入。</p><p class="civil-loading" role="status">${esc(civilLoadMessage)}</p></section><section class="section"><h2>开源项目与公开学习资料</h2><p>以下项目已分类整理。模块功能由本站独立实现；不安装第三方后端、不承诺 AI 批改或官方预测分，也不镜像付费课程。</p><div class="civil-resource-grid">${civilResources.map(r=>`<article><span class="chip">${r.kind}</span><h3>${r.name}</h3><p>${r.note}</p><a href="${r.url}" target="_blank" rel="noopener noreferrer">打开原项目或原页面</a></article>`).join('')}</div></section>`;}
function civilDialogHTML(){const d=civilDialog;if(!d)return '';return `<div class="civil-modal-backdrop"><section class="civil-modal" role="dialog" aria-modal="true" aria-labelledby="civil-dialog-title"><h2 id="civil-dialog-title">${d.type==='finish'?'确认交卷':d.type==='replace'?'有一份尚未结束的练习':'题目已载入'}</h2>${d.type==='finish'?`<p>还有 ${civilSession().questions.filter(id=>!civilSession().answers[id]?.length).length} 题未选答案。交卷后本次答案锁定并生成报告。</p><button class="primary" data-civil="finish">确认交卷</button><button class="secondary" data-civil="close-dialog">返回继续答</button>`:d.type==='replace'?`<p>原练习会保留在历史中，可稍后恢复；限时模考的截止时间继续有效。</p><button class="primary" data-civil="replace">保留记录，开始新练习</button><button class="secondary" data-civil="close-dialog">取消</button>`:`<p>${esc(d.label)} · ${d.questions.length}题</p>${d.issues?.length?`<p class="civil-boundary">${esc(d.issues.join('；'))}。这是部分或待核内容，不冒充完整核验套卷。</p>`:''}<label>自定义限时（分钟）<input id="civil-paper-minutes" type="number" min="1" max="240" value="120"></label><div class="hero-actions"><button class="primary" data-civil="loaded-start" data-mode="practice">逐题练习</button><button class="secondary" data-civil="loaded-start" data-mode="exam">限时作答</button></div><button class="text-button" data-civil="close-dialog">先留在题库</button>`}</section></div>`;}
function civilDownload(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function civilImportFiles(files){const questions=[],issues=[],images=[];let backup=null;for(const file of files){const relative=file.webkitRelativePath||file.name;if(/\.(png|jpe?g|webp|gif)$/i.test(relative)){images.push([relative,file]);continue;}if(/\.zip$/i.test(relative)){if(file.size>400*1024*1024)throw Error('ZIP 超过400MB，请用电脑文件夹导入。');const zip=await JSZip.loadAsync(await file.arrayBuffer()),entries=Object.values(zip.files);if(entries.length>50000||entries.reduce((n,f)=>n+(f._data?.uncompressedSize||0),0)>600*1024*1024)throw Error('ZIP 解压总量或文件数超过限制。');for(const entry of entries){if(entry.dir)continue;if(/\.md$/i.test(entry.name)&&entry._data.uncompressedSize<2*1024*1024){const result=Civil.parseMarkdown(await entry.async('string'),entry.name.replace(/^[^/]+\//,''));questions.push(...result.questions);issues.push(...result.issues);}else if(/\.(png|jpe?g|webp|gif)$/i.test(entry.name)&&entry._data.uncompressedSize<8*1024*1024){images.push([entry.name,await entry.async('blob')]);}}}else if(/\.md$/i.test(relative)){if(file.size>2*1024*1024){issues.push({reason:file.name+'过大，已跳过'});continue;}const result=Civil.parseMarkdown(await file.text(),relative.replace(/^[^/]+\/(?=0[1-6]-)/,''));questions.push(...result.questions);issues.push(...result.issues);}else if(/\.json$/i.test(relative)){if(file.size>30*1024*1024)throw Error('JSON文件限30MB。');const data=JSON.parse(await file.text());if(data.format==='learning-civil-backup-v1')backup=data;const rows=Array.isArray(data)?data:data.questions;if(!Array.isArray(rows))throw Error('JSON需要题目数组或{questions:[...]}。');for(const row of rows){try{questions.push(Civil.validateQuestion(row));}catch(e){issues.push({reason:e.message});}}}}
 for(const [path,file] of images){const at=path.indexOf('90-图片/');civilImages.set(at>=0?path.slice(at):file.name,file);}await civilRemember(questions);if(backup){if(!civilValidState(backup.state))throw Error('备份中的学习记录格式无效。');civilState={...civilState,...backup.state,version:1};civilPersist();}civilLoadMessage=`导入 ${questions.length} 道题，关联 ${images.length} 张图片${issues.length?'；'+issues.length+' 项待核':''}。`;civilGo('resources');toast(civilLoadMessage);}
const civilBaseNav=hubNav,civilBaseRender=render,civilBaseHome=hubHome;
hubNav=function(){return civilBaseNav().replace('</nav>',`<button data-civil="pane" data-id="home" ${view==='civil'||hubSubject==='civil'?'aria-current="page"':''}>考公刷题</button></nav>`);};
hubHome=function(){return civilBaseHome().replace('<span class="card-link">0 节引导课</span>','<span class="card-link">专项、真题、方法课与错题复习</span>');};
render=function(){if(view==='subject'&&hubSubject==='civil'){view='civil';civilPane='home';}if(view==='civil'&&civilPane!=='question'){const s=civilSession();if(s&&!s.finished&&!s.paused&&s.mode==='practice'){Civil.recordTime(s);s.paused=true;civilPersist();}}if(view!=='civil'){const s=civilSession();if(s&&!s.finished&&!s.paused&&s.mode==='practice'){Civil.recordTime(s);s.paused=true;civilPersist();}return civilBaseRender();}if(civilReady&&civilSession()?.mode==='exam'&&!civilSession().finished&&Date.now()>=civilSession().deadline)civilFinish();const content=civilPane==='home'?civilHomeHTML():civilPane==='question'?civilQuestionHTML():civilPane==='report'?civilReportHTML():civilPane==='papers'?civilPapersHTML():civilPane==='methods'?civilMethodsHTML():civilPane==='notebook'?civilNotebookHTML():civilPane==='stats'?civilStatsHTML():civilResourcesHTML();$('app').innerHTML=hubNav()+civilShell(content);const bar=document.querySelector('.subject-bar');if(bar){const wrap=document.createElement('details');wrap.className='classroom-switcher civil-switcher';const summary=document.createElement('summary');summary.textContent='考公刷题 · 切换学习领域';bar.before(wrap);wrap.append(summary,bar);}$('civil-start-form')?.addEventListener('submit',e=>{e.preventDefault();const category=$('civil-category').value,pool=$('civil-pool').value,questions=[...civilBank.values()].filter(q=>(category==='全部'||q.category===category)&&(pool==='all'||(pool==='original')===(q.source==='知行学习室原创')));civilStart(civilPick($('civil-order').value==='difficulty'?civilSortByDifficulty(questions):questions,Number($('civil-count').value),$('civil-order').value==='random',String(Date.now())),$('civil-mode').value,Math.min(240,Math.max(1,Number($('civil-minutes').value)||20)),category+'专项');});civilPaintDemo();civilTick();};
document.addEventListener('change',async e=>{const t=e.target;try{if(t.id.startsWith('paper-module-'))civilPaperModules[t.id.slice('paper-module-'.length)]=t.value;if(t.name==='civil-answer'){const s=civilSession(),q=civilCurrent();if(s&&q&&Civil.select(s,q,t.value)){civilPersist();render();$('civil-option-'+t.value)?.focus();}}if(t.id==='civil-year'){civilYear=t.value;civilCatalogPage=0;render();}if(t.id==='civil-region'){civilRegion=t.value;civilCatalogPage=0;render();}if(t.id==='civil-method-tier'){civilMethodTier=t.value;render();}if(t.id==='civil-method-category'){civilMethodCategory=t.value;render();}if(['civil-import-file','civil-folder-file'].includes(t.id)){civilLoadMessage='正在导入，请稍候…';const status=document.querySelector('.civil-loading');if(status)status.textContent=civilLoadMessage;await civilImportFiles([...t.files]);}if(t.id==='civil-image-files'){for(const file of t.files){const match=[...document.querySelectorAll('.civil-question img')].find(n=>decodeURIComponent(n.src).endsWith('/'+file.name));const src=match?decodeURIComponent(match.src.split('/main/')[1]):(/formula-/.test(file.name)?'90-图片/公式图/':'90-图片/题目图/')+file.name;civilImages.set(src,file);}render();toast('配图已关联到本次页面会话。');}}catch(error){toast(error.message);}});
document.addEventListener('input',e=>{if(e.target.id.startsWith('civil-demo-'))civilPaintDemo();});
document.addEventListener('click',async e=>{const el=e.target.closest('[data-civil]');if(!el||el.disabled)return;const d=el.dataset,a=d.civil;try{if(a==='pane')civilGo(d.id);if(a==='module')civilStart(civilPick([...civilBank.values()].filter(q=>q.category===d.id),10,true,String(Date.now())),'practice',20,d.id+'专项');if(a==='daily')civilStart(civilPick([...civilBank.values()].filter(q=>q.source==='知行学习室原创'),civilState.dailyGoal,true,civilToday()),'practice',20,'每日一练');if(a==='resume'){if(!civilSession())return civilGo('home');if(civilSession().paused){civilSession().paused=false;civilSession().activeSince=Date.now();civilPersist();}civilGo(civilSession().finished?'report':'question');}if(a==='pause'){const s=civilSession();if(!s||s.finished||s.mode==='exam')return;if(s.paused){s.paused=false;s.activeSince=Date.now();}else{Civil.recordTime(s);s.paused=true;}civilPersist();render();}if(a==='submit-one'){const s=civilSession(),q=civilCurrent(),result=Civil.submitOne(s,q);if(result){civilRecordResult(q,result);s.recorded.push(q.id);civilPersist();render();}}if(a==='move'||a==='jump'){const s=civilSession();if(!s||s.paused)return;Civil.recordTime(s);const i=a==='jump'?Number(d.index):s.index+Number(d.delta);if(i>=0&&i<s.questions.length){s.index=i;civilPersist();render();document.querySelector('.civil-session-bar')?.scrollIntoView({block:'start',behavior:'instant'});}}if(a==='bookmark'){const id=civilCurrent().id;civilState.bookmarks=civilState.bookmarks.includes(id)?civilState.bookmarks.filter(x=>x!==id):[...civilState.bookmarks,id];civilPersist();render();}if(a==='flag'){const s=civilSession(),id=civilCurrent().id;s.flags=s.flags.includes(id)?s.flags.filter(x=>x!==id):[...s.flags,id];civilPersist();render();}if(a==='ask-finish'){civilDialog={type:'finish'};render();}if(a==='finish')civilFinish();if(a==='close-dialog'){civilDialog=null;render();}if(a==='replace'){const x=civilDialog;civilStart(x.questions,x.mode,x.minutes,x.label,true);}if(a==='loaded-start'){const x=civilDialog,minutes=Number($('civil-paper-minutes').value)||120;civilDialog=null;civilStart(x.questions,d.mode,Math.min(240,Math.max(1,minutes)),x.label);}if(a==='review-current'){civilSession().index=0;civilGo('question');}if(a==='redo-wrong'){const s=civilSession();civilStart(s.questions.filter(id=>['wrong','blank'].includes(s.submitted[id]?.result)).map(id=>civilBank.get(id)).filter(Boolean),'practice',20,'本次错题重做');}if(a==='reload-catalog')civilLoadCatalog();if(a==='search-papers'){civilPaperQuery=$('civil-paper-query').value.trim();civilCatalogPage=0;render();}if(a==='papers-page'){civilCatalogPage=Math.max(0,civilCatalogPage+Number(d.delta));render();}if(a==='load-paper')await civilLoadPaper(d.id,$('paper-module-'+d.id).value);if(a==='method'){civilMethodId=d.id;civilGo('methods');}if(a==='method-back'){civilMethodId='';render();}if(a==='method-done'){civilState.methods=[...new Set([...civilState.methods,d.id])];civilPersist();render();}if(a==='method-practice'){civilState.methods=[...new Set([...civilState.methods,d.id])];civilPersist();const questions=[...civilBank.values()].filter(q=>q.method===d.id);civilStart(questions.length?questions:[...civilBank.values()].filter(q=>civilMethods.find(m=>m.id===d.id).category==='全模块'||q.category===civilMethods.find(m=>m.id===d.id).category).slice(0,5),'practice',20,'方法练习 · '+civilMethods.find(m=>m.id===d.id).title);}if(a==='notebook-filter'){civilReviewOnly=d.id;render();}if(a==='practice-notebook'){const ids=[...document.querySelectorAll('[data-civil="single"]')].map(n=>n.dataset.id);civilStart(ids.map(id=>civilBank.get(id)).filter(Boolean),'practice',20,'错题与收藏复习');}if(a==='review-due'){const qs=[...civilBank.values()].filter(q=>civilState.records[q.id]?.review?.due<=Date.now());civilStart(qs,'practice',20,'到期复习');}if(a==='single')civilStart([civilBank.get(d.id)],'practice',20,'独立重做');if(a==='inspect'){civilReviewId=d.id;const q=civilBank.get(d.id);$('app').innerHTML=hubNav()+civilShell(`<button data-civil="pane" data-id="notebook" class="text-button">返回错题本</button><article class="section"><div class="civil-stem">${civilHTML(q.stem,q)}</div>${q.material?civilHTML(q.material,q):''}${civilExplanationHTML(q)}</article>`);}if(a==='save-note'){civilState.notes[d.id]={...civilState.notes[d.id],reason:$('civil-reason').value,text:$('civil-note').value};civilPersist();toast('复盘已保存。');}if(a==='question-doubt'){civilState.notes[d.id]={...civilState.notes[d.id],doubt:!civilState.notes[d.id]?.doubt};civilPersist();toast(civilState.notes[d.id].doubt?'已标记待核，后续不会自动评分。':'已取消待核标记。');}if(a==='save-goal'){civilState.dailyGoal=Math.min(300,Math.max(1,Number($('civil-goal').value)||10));civilPersist();toast('每日目标已保存。');}if(a==='history'){const found=[civilSession(),...civilState.history].find(s=>s?.id===d.id);if(!found)return;if(civilSession()&&civilSession().id!==found.id){Civil.recordTime(civilSession());civilState.history=[civilSession(),...civilState.history.filter(s=>s.id!==found.id&&s.id!==civilSession().id)].slice(0,30);}civilState.active=found;found.paused=false;found.activeSince=Date.now();civilPersist();civilGo(found.finished?'report':'question');}if(a==='import')$('civil-import-file').click();if(a==='folder')$('civil-folder-file').click();if(a==='images'){$('civil-image-files').click();}if(a==='export'){Civil.recordTime(civilSession()||{finished:true});const ids=new Set([...(civilSession()?.questions||[]),...civilState.history.flatMap(s=>s.questions),...Object.keys(civilState.records),...civilState.bookmarks]);civilDownload({format:'learning-civil-backup-v1',exported:new Date().toISOString(),state:civilState,questions:[...ids].map(id=>civilBank.get(id)).filter(Boolean)},'zhixing-civil-backup.json');}if(a==='template')civilDownload({questions:[civilSeed[0]]},'civil-question-template.json');}catch(error){toast(error.message||'操作未完成，请重试。');}});
window.addEventListener('pagehide',()=>{if(civilSession()&&!civilSession().finished){Civil.recordTime(civilSession());civilPersist();}});
document.addEventListener('visibilitychange',()=>{const s=civilSession();if(document.hidden&&s&&!s.finished&&s.mode==='practice'&&!s.paused){Civil.recordTime(s);s.paused=true;civilPersist();if(view==='civil')render();}});
setInterval(civilTick,1000);
document.addEventListener('error',e=>{const img=e.target;if(img?.tagName==='IMG'&&img.closest('.civil-main')){const hint=document.createElement('span');hint.className='civil-image-fallback';hint.textContent='配图加载失败；可在资料与导入中补充原仓库配图。';img.replaceWith(hint);}},true);
if(globalThis.location?.hash==='#civil')civilGo('home');else render();
civilHydrate();
